from enum import Enum

class Kind(Enum):
    SIGMA1 = 'Sigma_1'
    PI1 = 'Pi_1'
    OTHER = 'other'

class Bet(Enum):
    BET_TRUE = 'betTrue'
    BET_FALSE = 'betFalse'
    HEDGE = 'hedge'

def classify_and_bet(kind: Kind) -> Bet:
    """Return the provably optimal bet for a card of the given shape."""
    if kind is Kind.PI1:
        return Bet.BET_TRUE
    if kind is Kind.SIGMA1:
        return Bet.BET_FALSE
    return Bet.HEDGE

