from typing import List, Callable

def payoff(bet: Bet, truth: bool) -> int:
    if bet is Bet.HEDGE:
        return 0
    if bet is Bet.BET_TRUE:
        return 1 if truth else -1
    return -1 if truth else 1

def deck_profit(deck: List['Card'],
                strategy: Callable[[Kind], Bet] = classify_and_bet) -> int:
    """Total profit; equals the decidable-shape count for the winning strategy."""
    return sum(payoff(strategy(c.kind), c.truth) for c in deck)

def decidable_shape_count(deck: List['Card']) -> int:
    return sum(1 for c in deck if c.kind in (Kind.SIGMA1, Kind.PI1))

