from typing import List, Tuple

def one_third_certificate(deck: List['Card']) -> Tuple[bool, float]:
    """Certify a >= 1/3 per-round edge when decidable-shape density >= 1/3."""
    n = len(deck)
    if n == 0:
        return (False, 0.0)
    d = sum(1 for c in deck if c.kind in (Kind.SIGMA1, Kind.PI1))
    rho = d / n
    # guaranteed average profit per round equals rho (each such card pays +1)
    return (rho >= 1 / 3, rho)
